CREATE OR REPLACE FUNCTION public.create_voucher_batch(b jsonb, items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; r jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtext(b->>'request_key')); SELECT id INTO bid FROM voucher_batches WHERE request_key=(b->>'request_key')::uuid AND owner_id=(b->>'owner_id')::uuid; IF bid IS NOT NULL THEN RETURN bid; END IF; IF NOT EXISTS(SELECT 1 FROM routers WHERE id=(b->>'router_id')::uuid AND owner_id=(b->>'owner_id')::uuid) THEN RAISE EXCEPTION 'not_allowed'; END IF; IF jsonb_array_length(items) <> (b->>'requested')::integer OR (b->>'requested')::integer NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'invalid_count'; END IF; IF b->>'source'='hotspot' AND (b->'package_snapshot'->'issue_limits' IS NULL OR b->'package_snapshot'->'issue_limits'='null'::jsonb) THEN RAISE EXCEPTION 'limits_required'; END IF; INSERT INTO voucher_batches(owner_id,router_id,source,package_name,package_snapshot,label,requested,mode,request_key) VALUES((b->>'owner_id')::uuid,(b->>'router_id')::uuid,b->>'source',b->>'package_name',b->'package_snapshot',b->>'label',(b->>'requested')::integer,b->>'mode',(b->>'request_key')::uuid) RETURNING id INTO bid; FOR r IN SELECT value FROM jsonb_array_elements(items) LOOP IF (r->>'name') !~ '^[A-Za-z0-9._@-]{1,32}$' OR COALESCE(r->>'ciphertext','')='' THEN RAISE EXCEPTION 'invalid_item'; END IF; INSERT INTO voucher_items(id,batch_id,owner_id,router_id,source,name,ordinal) VALUES((r->>'id')::uuid,bid,(b->>'owner_id')::uuid,(b->>'router_id')::uuid,b->>'source',r->>'name',(r->>'ordinal')::integer); INSERT INTO voucher_secrets(item_id,ciphertext) VALUES((r->>'id')::uuid,r->>'ciphertext'); END LOOP; RETURN bid; END $$;
REVOKE ALL ON FUNCTION public.create_voucher_batch(jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.create_voucher_batch(jsonb,jsonb) TO service_role;
CREATE INDEX IF NOT EXISTS voucher_batch_owner_created ON public.voucher_batches(owner_id,created_at DESC);
CREATE INDEX IF NOT EXISTS voucher_pending_router ON public.voucher_items(router_id,state,lease_at);